// dsh-anim-pack / lib/shots.js
//
// Pure, host-free logic over the bundled shot-card library from
// Vincentwei1021/video-shotcraft (Apache-2.0): 124 recipe cards across 10
// categories, their 54 gallery posters, and the snapshot index generated by
// tools/build-shots.mjs.
//
// A "card" is one recipe (frontmatter: name / 一句话 / 适用 / 时长 / 能量 /
// 标签, body: 意图 / 动效核心 / 参数表 / 声音 / 已知坑 / 参考实现). The host
// never fetches anything: cards, posters and the index all live under
// assets/shots/ inside this package.
//
// No cordis / DSH imports here on purpose: tools/verify.mjs exercises this
// file directly with plain node.

import { copyFileSync, existsSync, mkdirSync, readFileSync, readdirSync, statSync, writeFileSync } from 'node:fs'
import { basename, join, resolve, sep } from 'node:path'

import { clampLimit } from './catalog.js'

/** Where the generated shot index lives inside the plugin root. */
export const SHOTS_CATALOG_REL = join('assets', 'shots', 'index.json')

/** The ten categories, in the order the upstream gallery lists them. */
export const SHOT_CATEGORIES = [
  { id: 'opening', name: '开场与品牌', blurb: '先立名号：字标、准星、品牌记忆点', styles: 11 },
  { id: 'camera', name: '运镜与空间', blurb: '2.5D 推拉摇移、拆解、环绕', styles: 13 },
  { id: 'transition', name: '转场', blurb: '卡片群、遮罩、翻页、闪切', styles: 19 },
  { id: 'typography', name: '文字与字卡', blurb: '文字隧道、逐字、字重与字号表演', styles: 25 },
  { id: 'ui-entrance', name: '界面登场', blurb: '页面、卡片、面板怎么进画', styles: 22 },
  { id: 'interaction', name: '交互演示', blurb: '点击、拖拽、换主题的真实反馈', styles: 13 },
  { id: 'data', name: '数据与指标', blurb: '数字滚动、坐标轴重缩放', styles: 9 },
  { id: 'effects', name: '光效与强调', blurb: '聚光、闪、glint、粒子', styles: 23 },
  { id: 'rhythm', name: '节奏与蒙太奇', blurb: '卡点闪切、多裁切蒙太奇', styles: 8 },
  { id: 'outro', name: '收尾', blurb: '归位、拼标、留白与 CTA', styles: 7 },
]

const CATEGORY_NAME = new Map(SHOT_CATEGORIES.map((row) => [row.id, row.name]))
const CATEGORY_INDEX = new Map(SHOT_CATEGORIES.map((row, i) => [row.id, i]))

/** Upstream project (kept in one place so the index and the tools agree). */
export const SHOTS_UPSTREAM = 'https://github.com/Vincentwei1021/video-shotcraft'
export const SHOTS_GALLERY = 'https://vincentwei1021.github.io/video-shotcraft/'

const fold = (text) => String(text ?? '').toLowerCase()

/** Frontmatter keys, in the order the cards write them. */
const FM_KEYS = ['name', '一句话', '适用', '时长', '能量', '标签']

/**
 * Split a card into frontmatter fields and body.
 * The cards use a flat `key: value` YAML block — no nesting, no multi-line
 * scalars — so a line parser is enough and keeps the package dependency-free.
 */
export function parseShotCard(text) {
  const source = String(text ?? '').replace(/^\uFEFF/, '').replace(/\r\n/g, '\n')
  const meta = {}
  let body = source
  if (source.startsWith('---')) {
    const end = source.indexOf('\n---', 3)
    if (end !== -1) {
      const block = source.slice(source.indexOf('\n') + 1, end)
      body = source.slice(end + 4).replace(/^\n/, '')
      for (const line of block.split('\n')) {
        if (!line.trim()) continue
        const at = line.indexOf(':')
        if (at < 1) continue
        const key = line.slice(0, at).trim()
        let value = line.slice(at + 1).trim()
        if ((value.startsWith('"') && value.endsWith('"')) || (value.startsWith("'") && value.endsWith("'"))) {
          value = value.slice(1, -1)
        }
        meta[key] = value
      }
    }
  }
  const tags = (meta['标签'] ?? '')
    .split(/[,，、;；|\/]+/)
    .map((tag) => tag.trim())
    .filter(Boolean)
  return {
    meta,
    body,
    tags,
    title: meta['一句话'] ?? '',
    fit: meta['适用'] ?? '',
    duration: meta['时长'] ?? '',
    energy: meta['能量'] ?? '',
  }
}

/** The `## 参考实现` line of a card: where the Remotion demo lives upstream. */
export function demoOf(body) {
  const text = String(body ?? '')
  const match = text.match(/^##\s*参考实现\s*$\n+([^\n]+)/m)
  return match ? match[1].trim() : ''
}

/** Headings of a card body, used for summaries and for the export README. */
export function sectionsOf(body) {
  return [...String(body ?? '').matchAll(/^##\s+(.+?)\s*$/gm)].map((m) => m[1])
}

/**
 * Load and normalise the shot index.
 * `dir` overrides the catalog location (config `shotsPath`); paths inside the
 * payload stay relative and absolute `filePath` / `previewPath` are added.
 */
export function loadShotCatalog(root, { dir = '' } = {}) {
  const base = resolve(root)
  const catalogPath = dir ? resolve(dir) : join(base, SHOTS_CATALOG_REL)
  let data
  try {
    data = JSON.parse(readFileSync(catalogPath, 'utf8'))
  } catch (error) {
    throw new Error(`cannot read shot catalog at ${catalogPath}: ${error?.message ?? error}`)
  }
  // 索引里记的相对路径是相对「assets/shots」这一层的，和 catalogPath 同一个目录树。
  const cardRoot = dir ? resolve(dir) : join(base, 'assets', 'shots')
  const textCache = new Map()
  const entries = (Array.isArray(data.entries) ? data.entries : []).map((entry) => ({
    ...entry,
    tags: Array.isArray(entry.tags) ? entry.tags : [],
    galleryUrl: entry.galleryUrl || data.gallery || SHOTS_GALLERY,
    filePath: entry.file ? join(cardRoot, entry.file) : '',
    previewPath: entry.preview ? join(cardRoot, entry.preview) : '',
  }))
  const byId = new Map(entries.map((entry) => [fold(entry.id), entry]))
  const bySlug = new Map()
  const byName = new Map()
  for (const entry of entries) {
    for (const [map, key] of [[bySlug, fold(entry.card)], [byName, fold(entry.title)]]) {
      if (!map.has(key)) map.set(key, [])
      map.get(key).push(entry)
    }
  }
  return {
    root: base,
    catalogPath,
    cardRoot,
    upstream: String(data.upstream ?? SHOTS_UPSTREAM),
    gallery: String(data.gallery ?? SHOTS_GALLERY),
    commit: String(data.commit ?? ''),
    commitShort: String(data.commitShort ?? ''),
    generated: String(data.generated ?? ''),
    license: String(data.license ?? 'Apache-2.0'),
    cards: Number(data.cards ?? entries.length),
    styles: Number(data.styles ?? 0),
    categories: (Array.isArray(data.categories) ? data.categories : []).map((row) => ({
      id: row.id,
      name: row.name ?? CATEGORY_NAME.get(row.id) ?? row.id,
      blurb: row.blurb ?? '',
      cards: Number(row.cards ?? 0),
      styles: Number(row.styles ?? 0),
    })),
    entries,
    byId,
    bySlug,
    byName,
    textCache,
  }
}

/** Read one card's Markdown, cached per catalog. */
export function readShotCard(catalog, entry) {
  if (!entry?.filePath) throw new Error(`card ${entry?.id ?? '?'} has no file`)
  if (catalog.textCache.has(entry.filePath)) return catalog.textCache.get(entry.filePath)
  const text = readFileSync(entry.filePath, 'utf8')
  catalog.textCache.set(entry.filePath, text)
  return text
}

/** Absolute path of a card's poster ('' when upstream never shipped one). */
export function shotPreviewPath(entry) {
  if (!entry?.previewPath) return ''
  return existsSync(entry.previewPath) ? entry.previewPath : ''
}

/** Resolve by id (`opening/brand-ink-open`), bare card name, or 一句话. */
export function resolveShot(catalog, value) {
  const raw = String(value ?? '').trim().replace(/\.md$/i, '')
  const key = fold(raw)
  if (!key) return { kind: 'missing', entry: null, candidates: [] }
  const direct = catalog.byId.get(key)
  if (direct) return { kind: 'exact', entry: direct, candidates: [] }
  const short = key.includes('/') ? key.split('/').pop() : key
  for (const map of [catalog.bySlug, catalog.byName]) {
    const hits = map.get(short) ?? map.get(key) ?? []
    if (hits.length === 1) return { kind: 'loose', entry: hits[0], candidates: [] }
    if (hits.length > 1) return { kind: 'ambiguous', entry: null, candidates: hits }
  }
  return { kind: 'missing', entry: null, candidates: [] }
}

/** Compact row used by search / random / listing. */
export function summarizeShot(entry, extra = {}) {
  return {
    id: entry.id,
    card: entry.card,
    category: entry.category,
    categoryName: entry.categoryName,
    title: entry.title,
    duration: entry.duration,
    energy: entry.energy,
    tags: entry.tags.slice(0, 6),
    hasPreview: Boolean(shotPreviewPath(entry)),
    galleryUrl: entry.galleryUrl || '',
    ...extra,
  }
}

function haystack(entry) {
  return fold([
    entry.id,
    entry.card,
    entry.category,
    entry.categoryName,
    entry.title,
    entry.fit,
    entry.duration,
    entry.energy,
    ...(Array.isArray(entry.tags) ? entry.tags : []),
  ].join(' '))
}

/** Lines of the card body that contain any search term (up to 2, trimmed). */
function bodyHits(catalog, entry, terms) {
  let text = ''
  try {
    text = readShotCard(catalog, entry)
  } catch {
    return []
  }
  const out = []
  for (const line of text.split('\n')) {
    const clean = line.trim()
    if (clean.length < 4 || clean.startsWith('---')) continue
    const folded = fold(clean)
    if (terms.some((term) => folded.includes(term))) {
      out.push(clean.length > 120 ? clean.slice(0, 120) + '…' : clean)
      if (out.length >= 2) break
    }
  }
  return out
}

/**
 * Search the cards. Every whitespace-separated term must appear in the card's
 * metadata OR in its body (so "打字机" finds the card that mentions it inside
 * 参数表). `deep: false` keeps it to metadata only.
 */
export function searchShots(catalog, {
  query = '',
  category = '',
  tag = '',
  energy = '',
  preview = null,
  deep = true,
  limit = 20,
} = {}) {
  let rows = catalog.entries
  const cat = fold(category).trim()
  if (cat) {
    rows = rows.filter((entry) => fold(entry.category) === cat || fold(entry.categoryName) === cat ||
      fold(entry.categoryName).includes(cat))
  }
  const wantTag = fold(tag).trim()
  if (wantTag) rows = rows.filter((entry) => entry.tags.some((value) => fold(value).includes(wantTag)))
  const wantEnergy = fold(energy).trim()
  if (wantEnergy) rows = rows.filter((entry) => fold(entry.energy).includes(wantEnergy))
  if (preview === true) rows = rows.filter((entry) => shotPreviewPath(entry))
  else if (preview === false) rows = rows.filter((entry) => !shotPreviewPath(entry))

  const q = fold(query).trim()
  const terms = q ? q.split(/\s+/).filter(Boolean) : []
  if (terms.length > 0) {
    const scored = []
    for (const entry of rows) {
      const hay = haystack(entry)
      const metaHit = terms.every((term) => hay.includes(term))
      if (metaHit) {
        const rank = fold(entry.id) === q ? 0 : fold(entry.card) === q ? 1 : fold(entry.id).startsWith(q) ? 2 : 3
        scored.push({ entry, rank, hits: [] })
        continue
      }
      if (!deep) continue
      // 正文命中也算命中，但仍要求「每个词都出现」——只是允许它出现在正文里。
      let body = ''
      try {
        body = readShotCard(catalog, entry)
      } catch {
        continue
      }
      const combined = hay + fold(body)
      if (!terms.every((term) => combined.includes(term))) continue
      scored.push({ entry, rank: 4, hits: bodyHits(catalog, entry, terms) })
    }
    scored.sort((a, b) => a.rank - b.rank || (CATEGORY_INDEX.get(a.entry.category) ?? 99) - (CATEGORY_INDEX.get(b.entry.category) ?? 99) || fold(a.entry.id).localeCompare(fold(b.entry.id)))
    return scored.slice(0, clampLimit(limit))
  }
  rows = rows.slice().sort((a, b) =>
    (CATEGORY_INDEX.get(a.category) ?? 99) - (CATEGORY_INDEX.get(b.category) ?? 99) || fold(a.card).localeCompare(fold(b.card)))
  return rows.slice(0, clampLimit(limit)).map((entry) => ({ entry, rank: 0, hits: [] }))
}

/** A random card, optionally narrowed by category / tag / preview availability. */
export function randomShot(catalog, { category = '', tag = '', energy = '', preview = null } = {}) {
  const pool = searchShots(catalog, { category, tag, energy, preview, deep: false, limit: catalog.entries.length || 1 })
  if (pool.length === 0) return null
  return pool[Math.floor(Math.random() * pool.length)].entry
}

/** Distribution over the whole library, for anim_shot_stats. */
export function shotStats(catalog) {
  const categories = catalog.categories.map((row) => ({
    ...row,
    posters: catalog.entries.filter((entry) => entry.category === row.id && shotPreviewPath(entry)).length,
  }))
  const withPoster = catalog.entries.filter((entry) => shotPreviewPath(entry)).length
  const energy = {}
  for (const entry of catalog.entries) {
    const key = (entry.energy || '未标注').split(/[（(]/)[0].trim() || '未标注'
    energy[key] = (energy[key] ?? 0) + 1
  }
  return {
    cards: catalog.cards || catalog.entries.length,
    styles: catalog.styles,
    categories,
    withPoster,
    withoutPoster: catalog.entries.length - withPoster,
    energy,
    tags: [...new Set(catalog.entries.flatMap((entry) => entry.tags))].sort(),
    upstream: catalog.upstream,
    gallery: catalog.gallery,
    commit: catalog.commitShort || catalog.commit,
    generated: catalog.generated,
    license: catalog.license,
  }
}

/** Refuse to write back into the package itself. */
function insideRoot(root, target) {
  const rel = resolve(target).slice(resolve(root).length)
  return resolve(target).startsWith(resolve(root)) && (rel === '' || rel.startsWith(sep))
}

/**
 * Copy cards (and posters) into a working directory:
 *   <dir>/<card>/<card>.md        the recipe, verbatim
 *   <dir>/<card>/<card>.jpg       the poster, when upstream shipped one
 *   <dir>/<card>/README.md        how to adapt it: upstream demo path, gallery link, sections
 *   <dir>/index.md                the list, grouped by category
 */
export function exportShots(catalog, entries, { dir } = {}) {
  const target = resolve(dir || '.')
  if (insideRoot(catalog.root, target)) {
    return { error: '导出目录不能是插件本体（' + catalog.root + '），换一个工作目录。' }
  }
  mkdirSync(target, { recursive: true })
  const rows = []
  const files = []
  const used = new Set()
  for (const entry of entries) {
    let folder = entry.card
    let n = 2
    while (used.has(folder)) folder = entry.card + '-' + n++
    used.add(folder)
    const outDir = join(target, folder)
    try {
      mkdirSync(outDir, { recursive: true })
      copyFileSync(entry.filePath, join(outDir, folder + '.md'))
      files.push(join(outDir, folder + '.md'))
      const poster = shotPreviewPath(entry)
      if (poster) {
        copyFileSync(poster, join(outDir, folder + '.jpg'))
        files.push(join(outDir, folder + '.jpg'))
      }
      const text = readShotCard(catalog, entry)
      const parsed = parseShotCard(text)
      const demo = demoOf(parsed.body)
      const readme = [
        '# ' + folder,
        '',
        '- 分类：' + entry.categoryName + '（' + entry.category + '）',
        '- 一句话：' + entry.title,
        '- 适用：' + entry.fit,
        '- 时长：' + entry.duration,
        '- 能量：' + entry.energy,
        '- 卡片：' + entry.id,
        '- 上游：' + (entry.source || catalog.upstream),
        '- 在线样片：' + (entry.galleryUrl || catalog.gallery),
        '',
        '## 怎么用',
        '',
        '1. 「' + folder + '.md」是镜头配方卡：意图、动效核心、参数表、声音、已知坑都在里面，照着改参数。',
        '2. 需要现成代码就把上游 demos 目录里对应实现取过来（路径见卡片「参考实现」一段）：' + (demo || '（卡片没写）'),
        '3. 模板/镜头库本体由 video-shotcraft 提供（Remotion）；只借镜头语言时不必装它，按参数表在本机实现即可。',
        '',
        '## 章节',
        '',
        ...sectionsOf(parsed.body).map((name) => '- ' + name),
        '',
      ].join('\n')
      writeFileSync(join(outDir, 'README.md'), readme)
      files.push(join(outDir, 'README.md'))
      rows.push({ id: entry.id, dir: outDir, poster: Boolean(poster) })
    } catch (error) {
      rows.push({ id: entry.id, ok: false, error: String(error?.message ?? error) })
    }
  }
  const index = ['# 镜头卡导出', '', '来源：' + catalog.upstream + '（Apache-2.0）', '', '| 卡片 | 分类 | 时长 | 有海报 |', '|---|---|---|---|']
  for (const row of rows) {
    const entry = entries.find((item) => item.id === row.id)
    index.push('| ' + row.id + ' | ' + (entry?.categoryName ?? '') + ' | ' + (entry?.duration ?? '') + ' | ' + (row.poster ? '✓' : '—') + ' |')
  }
  writeFileSync(join(target, 'index.md'), index.join('\n') + '\n')
  files.push(join(target, 'index.md'))
  return { dir: target, rows, files }
}
